package main

import (
  "context"
  "fmt"
  "time"

  sdk "github.com/redwood-inference/go-sdk"
)

func main() {
  ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
  defer cancel()

  client := sdk.NewClient(sdk.WithAPIKey("REDACTED"))

  // Start a stream with AutoAck disabled (explicit ack)
  stream, err := client.StartStream(ctx, &sdk.StreamOptions{AutoAck: false})
  if err != nil {
    panic(err)
  }

  // Read a few messages and then detach so UI can reconnect later
  for i := 0; i < 3; i++ {
    msg, err := stream.Recv(ctx)
    if err != nil {
      fmt.Println("recv error:", err)
      break
    }
    fmt.Println("got:", msg.ID, string(msg.Data))
    // explicit ack after durable processing
    _ = stream.Ack(msg.ID)
  }

  // Detach returns an opaque token which can be stored by the client
  token, err := stream.Detach()
  if err != nil {
    panic(err)
  }
  // stream.Close() doesn't cancel server-side consumption when detached; it just cleans local state
  _ = stream.Close()

  // ... later (maybe different process) we attempt to resume 
  resumeCtx, resumeCancel := context.WithTimeout(context.Background(), 10*time.Second)
  defer resumeCancel()

  resumed, err := client.ResumeStream(resumeCtx, token)
  if err != nil {
    fmt.Println("resume failed:", err)
    return
  }

  for {
    msg, err := resumed.Recv(resumeCtx)
    if err != nil {
      fmt.Println("finished/err:", err)
      break
    }
    fmt.Println("resumed got:", msg.ID)
    // if processing might take long, use a per-message context derived from resumeCtx with its own deadline
    procCtx, procCancel := context.WithTimeout(resumeCtx, 2*time.Second)
    _ = resumed.Ack(msg.ID)
    procCancel()
  }
}
